  xm20 N004 Vbias2 N008 VDD sky130_fd_pr__pfet_01v8 w={W_xm20} l={L_xm20}
  xm21 Vpcas Vpcas N004 VDD sky130_fd_pr__pfet_01v8 w={W_xm21} l={L_xm21}
  xm22 Vbias3 Vbias3 0 0 sky130_fd_pr__nfet_01v8 w={W_xm22} l={L_xm22}
  xm23 Vpcas Vbias3 N011 0 sky130_fd_pr__nfet_01v8 w={W_xm23} l={L_xm23}
  xm24 N011 Vbias4 0 0 sky130_fd_pr__nfet_01v8 w={W_xm24} l={L_xm24}
  xm25 Vbias4 Vbias3 Vlow 0 sky130_fd_pr__nfet_01v8 w={W_xm25} l={L_xm25}
  xm26 Vlow Vbias4 0 0 sky130_fd_pr__nfet_01v8 w={W_xm26} l={L_xm26}
.ends SUB_1

.control
* 1. Operating Point Analysis
op
let id1_q = i(VID1)
let id2_q = i(VID2)
let vbias_batt = v(N001) - v(N1)
let p_diss = -i(VDD) * 1.8

print id1_q id2_q vbias_batt p_diss

* 2. DC Sweep Analysis (sweeping VI1 across differential input range)
dc VI1 0.8 1.8 0.005

let id1_sweep = i(VID1)
let id2_sweep = i(VID2)
let id_diff = id1_sweep - id2_sweep

* Measure peak currents
meas dc peak_id1 max id1_sweep
meas dc peak_id2 max id2_sweep
meas dc id1_at_high find id1_sweep at=1.6
meas dc id2_at_low find id2_sweep at=0.92

* Measure quiescent currents in DC sweep
meas dc id1_quiescent find id1_sweep at=1.26
meas dc id2_quiescent find id2_sweep at=1.26

* Measure transconductance around VI1 = 1.26V
let gm_diff = deriv(id_diff)
meas dc gm_at_eq find gm_diff at=1.26

* Measure boost ratio
let boost = id1_at_high / id1_quiescent
print boost

quit
.endc
.end

